SourceCode.Declaration:
class FMCustomerListItem extends FMCustomerPage
{
    private str customerFirstNameInternal;
    private str customerLastNameInternal;
    private ImageReference custImage;
    private str driversLicense;

}

Method.Source:
[SysAppField(fieldStr(FMCustomer, FirstName), "Customer first name")]
public str customerFirstName(str _value=customerFirstNameInternal)
{
    customerFirstNameInternal = _value;
    return customerFirstNameInternal;
}

[SysAppField(fieldStr(FMCustomer, LastName), "Customer last name")]
public str customerLastName(str _value=customerLastNameInternal)
{
    customerLastNameInternal = _value;
    return customerLastNameInternal;
}

[SysAppField(fieldStr(FMCustomer, Image), "Customer image")]
public ImageReference customerImage(ImageReference _value=custImage)
{
    custImage = _value;
    return custImage;
}

[SysAppField(fieldStr(FMCustomer, DriverLicense), "Drivers license")]
public str driverLicenseNumber(str _value=driversLicense)
{
    driversLicense = _value;
    return driversLicense;
}

public void populate(FMCustomer _customerTable)
{
    this.customerFirstName(_customerTable.FirstName);
    this.customerLastName(_customerTable.LastName);
    this.driverLicenseNumber(_customerTable.DriverLicense);

    if (_customerTable.Image != conNull())
    {
        Image img = new Image();
        img.setData(_customerTable.Image);
        this.customerImage(ImageReference::constructForImage(img));
    }

    this.RecId(_customerTable.RecId);
}
